# Build archive song keys (title, artist) lowercased
archive_keys = set()
for title, artist in archive_songs:
    if artist:
        archive_keys.add((title.lower(), artist.lower()))
    else:
        archive_keys.add((title.lower(), None))

# Find matching song IDs from song_details
matching_song_ids = set()
for sid, song in song_details.items():
    title_lower = song['title'].lower()
    artist_names = [a['name'].lower() for a in song['artists']]
    # Check if any archive key matches
    for key_title, key_artist in archive_keys:
        if title_lower == key_title:
            if key_artist is None or key_artist in artist_names:
                matching_song_ids.add(sid)
                break

print("Matching song IDs:", len(matching_song_ids))
print(sorted(matching_song_ids))

